+	t.Helper()
+	logger, _ := newTestLogger()
+	tc := newTestLoop(t, logger)
+	if err := tc.loop.loadOrBootstrapCanonical(); err != nil {
+		t.Fatal(err)
+	}
+	return tc
+}
